select '00000000-0000-4000-8000-000000000002', "id", "sort", "title", "area", "horizon", "status", "go", "votes", "asked_by", "refs", "why", "what", "collab", "extra" from jsonb_populate_recordset(null::public."product_roadmap_items", $rwdr0e9$[{"id":"RM40","sort":35,"title":"One owner, contributors and followers on every object","area":"Collaboration","horizon":"done","status":"Shipped","go":"wk-raci","votes":18,"asked_by":["S","P","F"],"refs":["Asana","Linear","WorkBoard","Perdoo"],"why":"Objectives, measures, key results, initiatives, risks and tasks each need one accountable owner, with named contributors who can update and followers who are kept informed.","what":"One owner on every record, with contributors, people to consult and followers; a Who does what page flags missing or double owners.","collab":1,"extra":null},{"id":"RM41","sort":36,"title":"Accept, decline or propose a new date","area":"Collaboration","horizon":"done","status":"Shipped","go":"wk-my","votes":17,"asked_by":["F","P","S"],"refs":["Linear","Profit.co"],"why":"Work is assigned, but nobody agrees to it. Almost no tool asks for agreement, and strategy owners want it.","what":"Tasks, actions and hand-overs are accepted, declined with a reason, or answered with a new date; committed dates are kept apart from due dates.","collab":1,"extra":null},{"id":"RM42","sort":37,"title":"Comment threads on every object","area":"Collaboration","horizon":"done","status":"Shipped","go":"wk-raci","votes":16,"asked_by":["S","P","F"],"refs":["Linear","Notion","ClickUp","Confluence"],"why":"Today only tasks and status updates can be discussed; decisions, measures, gates, risks and budgets cannot.","what":"Threads with replies, mentions, reactions and resolve on tasks, measures, objectives, initiatives, decisions, risks and actions; a thread can become an action or a decision.","collab":1,"extra":null},{"id":"RM43","sort":38,"title":"Milestones with acceptance and evidence","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-portfolio","votes":14,"asked_by":["P","S"],"refs":["Planview","Wrike","Planisware"],"why":"Milestones are quarters that count as met once the date passes.","what":"Named milestones with an accepter, criteria and evidence; met only when accepted; late milestones flag the key results that depend on them.","collab":1,"extra":null},{"id":"RM44","sort":39,"title":"Catchball and target agreement","area":"Strategy","horizon":"done","status":"Shipped","go":"st-agree","votes":13,"asked_by":["S"],"refs":["Profit.co","WorkBoard","i-nexus","Perdoo"],"why":"Unit objectives and targets go live at once, with nothing proposed or agreed.","what":"Draft, propose, counter-propose, agree and lock targets; alignment requests; shared key results with accepted team shares.","collab":1,"extra":null},{"id":"RM45","sort":40,"title":"Review meetings that produce owned work","area":"Strategy","horizon":"done","status":"Shipped","go":"st-meet","votes":12,"asked_by":["S","P"],"refs":["WorkBoard","Fellow","Confluence"],"why":"Steering actions never reach the owner, and reviews have no agenda, pre-reads or minutes.","what":"Attendees, an agenda built from exceptions, pre-reads, minutes, and actions that land in the owner's My work and carry forward until done.","collab":1,"extra":null},{"id":"RM46","sort":41,"title":"Resource requests with negotiation","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-capacity","votes":10,"asked_by":["P"],"refs":["ServiceNow SPM","Planview","Tempus Resource"],"why":"Capacity is a number per role, with no request or confirmation.","what":"Request a role or person; the line manager confirms, books, proposes another option or declines; bookings sit beside capacity.","collab":1,"extra":null},{"id":"RM47","sort":42,"title":"Absence cover and hand-over","area":"Work","horizon":"done","status":"Shipped","go":"wk-teams","votes":9,"asked_by":["F","S"],"refs":["monday.com","Asana"],"why":"Work stalls when someone is away, and a change of owner leaves no note.","what":"Time off with a named cover who receives new work; hand-overs take effect when the new owner accepts.","collab":1,"extra":null},{"id":"RM48","sort":43,"title":"Team triage queues","area":"Work","horizon":"done","status":"Shipped","go":"wk-teams","votes":8,"asked_by":["F"],"refs":["Linear","Jira","monday.com"],"why":"Small requests have no front door between personal tasks and portfolio requests.","what":"A triage queue per team with accept, decline, merge and snooze, a rotating triage owner and round robin that skips people who are away.","collab":1,"extra":null},{"id":"RM49","sort":44,"title":"Committed and stretch targets with say/do","area":"Strategy","horizon":"done","status":"Shipped","go":"st-commit","votes":9,"asked_by":["S","F"],"refs":["WorkBoard","Atlassian","Jira","Linear"],"why":"Not every key result is a promise. Leaders want to see who delivers what they commit to.","what":"Committed and stretch targets; status uses the committed one; say/do rates per owner and team for each period.","collab":1,"extra":null},{"id":"RM50","sort":45,"title":"An inbox you can act from","area":"Collaboration","horizon":"done","status":"Shipped","go":"wk-my","votes":9,"asked_by":["F"],"refs":["Linear","Asana","ClickUp"],"why":"The inbox can only be read and archived.","what":"Updates bundled per item; reply, accept, approve and snooze from the inbox; quiet hours.","collab":1,"extra":null},{"id":"RM51","sort":46,"title":"Workload you can act on","area":"Work","horizon":"done","status":"Shipped","go":"wk-tasks","votes":8,"asked_by":["F","P"],"refs":["Asana","monday.com","Wrike"],"why":"Overdue work disappears from future weeks, so overload is hidden.","what":"Overdue work carried forward, an unassigned row, time off shown, drag to reassign and a warning before overloading someone.","collab":1,"extra":null},{"id":"RM52","sort":47,"title":"Done criteria and review before completion","area":"Work","horizon":"done","status":"Shipped","go":"wk-tasks","votes":7,"asked_by":["F","P"],"refs":["Jira","Asana"],"why":"Mark complete asks for nothing, and in some tools a rejected approval still counts as done.","what":"Done criteria and an optional reviewer; a reviewed task completes only when the reviewer approves.","collab":1,"extra":null},{"id":"RM60","sort":52,"title":"Link accounts to people","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-workspace","votes":9,"asked_by":["F"],"refs":["Asana","Linear"],"why":"In a shared workspace, task and check-in history is still credited to the demo person; only the audit log shows the real account.","what":"Each member is linked to a person, so their work, comments and approvals carry their own name.","collab":null,"extra":null},{"id":"RM61","sort":53,"title":"One status model on every strategy page","area":"Strategy","horizon":"done","status":"Shipped","go":"st-ogsm","votes":10,"asked_by":["S"],"refs":["Cascade","ClearPoint"],"why":"OGSM, V2MOM, the X-matrix and the ambition page still keep their own hand-set statuses and baselines, so they can disagree with the scorecard.","what":"OGSM, V2MOM, the X-matrix, the ambition and the heat map read the same calculated statuses, targets and baselines.","collab":null,"extra":null},{"id":"RM63","sort":55,"title":"Approved date changes move dependent work","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-portfolio","votes":6,"asked_by":["P"],"refs":["Microsoft Planner","Smartsheet"],"why":"Approving a later end date lists the dependent initiatives but does not move them.","what":"Approving a later end date offers to move each dependent initiative or raise a change request for it.","collab":null,"extra":null},{"id":"RM64","sort":56,"title":"Capex and opex by month","area":"Portfolio","horizon":"done","status":"Shipped","go":"budgets","votes":5,"asked_by":["P"],"refs":["Broadcom Clarity","Planview"],"why":"The capex share is one figure per initiative.","what":"Capex and opex split month by month in the finance grid and the budget totals.","collab":null,"extra":null},{"id":"RM65","sort":57,"title":"Project and task templates","area":"Work","horizon":"done","status":"Shipped","go":"wk-templates","votes":8,"asked_by":[],"refs":["Asana","monday.com","Smartsheet"],"why":"Every new initiative or project starts from scratch.","what":"Save an initiative or project as a template with tasks, phases, roles and gates, and start new work from it.","collab":null,"extra":null},{"id":"RM66","sort":58,"title":"Recurring tasks","area":"Work","horizon":"done","status":"Shipped","go":"wk-templates","votes":6,"asked_by":[],"refs":["Asana","ClickUp","Wrike"],"why":"Monthly closes, check-ins and reviews have to be added by hand each time.","what":"Tasks that repeat weekly, every two weeks, monthly or every three months; completing one creates the next.","collab":null,"extra":null},{"id":"RM67","sort":59,"title":"Live demo dates and fresh sample data","area":"Platform","horizon":"done","status":"Shipped","go":"dashboard","votes":7,"asked_by":["F"],"refs":[],"why":"The demo is fixed on 16 September 2024; resource data is from 2023 and RAID review dates are in the past.","what":"New demo sessions move the demo company's dates to the current year; the code has no fixed years.","collab":null,"extra":null},{"id":"RM68","sort":60,"title":"One date format everywhere","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-dates","votes":4,"asked_by":["F"],"refs":[],"why":"Project cards use month-first dates while the rest of the app uses day-first.","what":"Dates follow a workspace setting: day first, month first or ISO, everywhere.","collab":null,"extra":null},{"id":"RM69","sort":61,"title":"Dashboard actions and assistant search on live data","area":"Work","horizon":"done","status":"Shipped","go":"dashboard","votes":5,"asked_by":[],"refs":[],"why":"The dashboard's Actions widget and the assistant's document search still read fixed sample lists.","what":"The dashboard's actions and the assistant's search read live tasks, actions and records.","collab":null,"extra":null}]$rwdr0e9$::jsonb)
