select '00000000-0000-4000-8000-000000000001', "id", "sort", "ref", "author_id", "posted_on", "body", "extra" from jsonb_populate_recordset(null::public."comments", $rjvytpr$[{"id":"task:I2-2:c1","ref":"task:I2-2","author_id":"OA","posted_on":"2024-09-11","body":"I can review courses 7 and 8 as soon as they land.","extra":null,"sort":1},{"id":"task:I7-1:c2","ref":"task:I7-1","author_id":"PR","posted_on":"2024-09-13","body":"Great. I'll send the invite for Thursday at 10:00.","extra":null,"sort":2},{"id":"task:I7-1:c3","ref":"task:I7-1","author_id":"DM","posted_on":"2024-09-14","body":"Which salary band are we offering? Let's agree it before the final panel.","extra":null,"sort":3},{"id":"task:I7-1:c4","ref":"task:I7-1","author_id":"PR","posted_on":"2024-09-15","body":"The band approved at the Q2 review. @Liza Martines can you confirm the budget line?","extra":null,"sort":4},{"id":"dec:D-15:c0","sort":0,"ref":"dec:D-15","author_id":"DN","posted_on":"2024-09-11","body":"Before the review: are the trainers free for the certification push in Q1?","extra":null},{"id":"dec:D-15:c1","sort":1,"ref":"dec:D-15","author_id":"OA","posted_on":"2024-09-12","body":"I'll check trainer availability with the practice leads.","extra":null},{"id":"dec:D-15:c2","sort":2,"ref":"dec:D-15","author_id":"JK","posted_on":"2024-09-12","body":"Courses 7 to 10 need two trainers until December.","extra":null},{"id":"init:I7:c0","sort":0,"ref":"init:I7","author_id":"PR","posted_on":"2024-09-05","body":"Should we ask the steering group for the £1.2M now, or wait until we have a country lead?","extra":null},{"id":"init:I7:c1","sort":1,"ref":"init:I7","author_id":"DM","posted_on":"2024-09-06","body":"Ask now and make it subject to hiring. Bring it to the Q3 review.","extra":null},{"id":"init:I9:c0","sort":0,"ref":"init:I9","author_id":"LM","posted_on":"2024-09-14","body":"Bundle prices are agreed with finance. Sales training starts in November.","extra":null},{"id":"kpi:K05:c0","sort":0,"ref":"kpi:K05","author_id":"LM","posted_on":"2024-09-09","body":"September dips to 87% because two renewals moved to October. Should we explain it in the check-in?","extra":null},{"id":"kpi:K05:c1","sort":1,"ref":"kpi:K05","author_id":"ML","posted_on":"2024-09-10","body":"Yes, I'll add it to the comment when I check in.","extra":null},{"id":"kpi:K05:c2","sort":2,"ref":"kpi:K05","author_id":"OA","posted_on":"2024-09-10","body":"Both renewals are signed for 1 October, so it recovers next month.","extra":null},{"id":"kpi:K05:c3","sort":3,"ref":"kpi:K05","author_id":"OA","posted_on":"2024-09-13","body":"Can we show the health-check score next to retention in the board pack?","extra":null},{"id":"obj:C2:c0","sort":0,"ref":"obj:C2","author_id":"LM","posted_on":"2024-09-10","body":"Should leads outside the Nordics count towards new markets?","extra":null},{"id":"obj:C2:c1","sort":1,"ref":"obj:C2","author_id":"PR","posted_on":"2024-09-11","body":"Only the Nordics for now. Other regions are ideas, not markets yet.","extra":null}]$rjvytpr$::jsonb)
